<template>
  <div class="popup-comp">
    <div class="close-btn" @click="$emit('close')">×</div>
    <div>
      <div class="popup-width">
        <div class="popup-inputs">
          <div class="pop-in">
            <input
                class="popup-input"
                :class="{'error' : nameError}"
                type="text"
                id="userName"
                name="userName"
                placeholder=" "
                v-model="name"
                @input="handleNameInput"
                @blur="validateName"
            >
            <label class="popup-label" for="userName">Имя</label>
            <div v-if="nameError" class="error-message">{{ nameError }}</div>
          </div>
          <div class="pop-in">
            <input
                ref="phoneInput"
                class="popup-input"
                :class="{'error': phoneError}"
                v-model="phone"
                type="tel"
                id="userTel"
                @blur="validatePhone"
                @input="handlePhoneInput"
                name="userTel"
                placeholder=" "
            >
            <label class="popup-label" for="userTel">Номер телефона </label>
            <div v-if="phoneError" class="error-message">{{ phoneError }}</div>
          </div>
          <div class="pop-in">
            <input
                class="popup-input"
                :class="{ 'error': emailError }"
                type="email"
                id="emailId"
                name="emailId"
                placeholder=" "
                v-model="email"
                @blur="validateEmail"
                @input="handleEmailInput"
            >
            <label class="popup-label" for="emailId">Email</label>
            <div v-if="emailError" class="error-message">{{ emailError }}</div>
          </div>
        </div>
      </div>
    </div>
    <div class="popup-pay">
      <div class="prices">
        <div class="fix-price">{{ formatPrice(price) }} ₽</div>
      </div>
      <div class="button-pay" @click="submitForm">Купить</div>
    </div>
    <div v-if="notification" :class="['popup-notification', notificationType]">
      {{ notification }}
    </div>
  </div>
</template>
<script setup>
import {ref, onMounted, computed, watch} from 'vue'
import {useRoute} from '#app'
import IMask from 'imask'
import axios from 'axios'
import { useRuntimeConfig } from '#app'

defineOptions({
  name: 'popupBeforePay',
})

defineEmits(['close'])

const props = defineProps({
  price: {
    required: true,
  },
  currentGuide:{},
})

const email = ref('')
const emailError = ref('')

const validateEmail = () => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/

  if (!email.value) {
    emailError.value = 'Email обязателен для заполнения'
    return false
  }

  if (!emailRegex.test(email.value)) {
    emailError.value = 'Введите корректный email адрес'
    return false
  }

  emailError.value = ''
  return true
}

const handleEmailInput = (event) => {
  const inputValue = event.target.value

  const transliterationMap = {
    'й': 'q', 'ц': 'w', 'у': 'e', 'к': 'r', 'е': 't', 'н': 'y', 'г': 'u', 'ш': 'i', 'щ': 'o', 'з': 'p',
    'ф': 'a', 'ы': 's', 'в': 'd', 'а': 'f', 'п': 'g', 'р': 'h', 'о': 'j', 'л': 'k', 'д': 'l',
    'я': 'z', 'ч': 'x', 'с': 'c', 'м': 'v', 'и': 'b', 'т': 'n', 'ь': 'm',
    'Й': 'Q', 'Ц': 'W', 'У': 'E', 'К': 'R', 'Е': 'T', 'Н': 'Y', 'Г': 'U', 'Ш': 'I', 'Щ': 'O', 'З': 'P',
    'Ф': 'A', 'Ы': 'S', 'В': 'D', 'А': 'F', 'П': 'G', 'Р': 'H', 'О': 'J', 'Л': 'K', 'Д': 'L',
    'Я': 'Z', 'Ч': 'X', 'С': 'C', 'М': 'V', 'И': 'B', 'Т': 'N', 'Ь': 'M'
  }

  const transliteratedValue = inputValue.replace(/[а-яА-Я]/g, (match) => {
    return transliterationMap[match] || match
  })

  email.value = transliteratedValue.toLowerCase()

  if (emailError.value) {
    emailError.value = ''
  }
}

const name = ref('')
const nameError = ref('')

const handleNameInput = (event) => {
  const inputValue = event.target.value

  const filteredValue = inputValue
      .replace(/[^а-яА-Яa-zA-Z\s-]/g, '')
      .replace(/^[\s-]+/, '')
      .replace(/\s+/g, ' ')
      .replace(/-+/g, '-')

  name.value = filteredValue

  if (nameError.value) {
    nameError.value = ''
  }
}

const validateName = () => {
  if (!name.value.trim()) {
    nameError.value = 'Имя обязательно к заполнению'
    return false
  }

  if (name.value.length < 2) {
    nameError.value = 'Имя должно содержать минимум 2 символа'
    return false
  }

  const nameRegex = /^[а-яА-Яa-zA-Z]+[\sа-яА-Яa-zA-Z-]*[а-яА-Яa-zA-Z]+$/
  if (!nameRegex.test(name.value)) {
    nameError.value = 'Введите корректное имя'
    return false
  }

  nameError.value = ''
  return true
}

const phone = ref('')
const phoneError = ref('')

const handlePhoneInput = (event) => {
  let value = event.target.value.replace(/[^\d+]/g, '')
  if (value[0] !== '+') value = '+' + value.replace(/^\+/, '')
  phone.value = value
  if (phoneError.value) phoneError.value = ''
}

const phoneInput = ref(null)

const route = useRoute()
const config = useRuntimeConfig()

onMounted(() => {
  if (phoneInput.value) {
    IMask(phoneInput.value, {
      mask: [
        {
          mask: '+{7} (000) 000-00-00',
          startsWith: '7',
          country: 'Russia'
        },
        {
          mask: '+{375} (00) 000-00-00',
          startsWith: '375',
          country: 'Belarus'
        },
        {
          mask: '+{380} (00) 000-00-00',
          startsWith: '380',
          country: 'Ukraine'
        },
        {
          mask: '+{1} (000) 000-0000',
          startsWith: '1',
          country: 'USA'
        },
        {
          mask: '+0000000000000',
        }
      ],
      dispatch: function (appended, dynamicMasked) {
        const number = (dynamicMasked.value + appended).replace(/\D/g, '')
        return dynamicMasked.compiledMasks.find(m => number.indexOf(m.startsWith) === 0) || dynamicMasked.compiledMasks[dynamicMasked.compiledMasks.length - 1]
      }
    })
  }
})

const validatePhone = () => {
  const digits = phone.value.replace(/\D/g, '')
  if (!digits) {
    phoneError.value = 'Телефон обязателен для заполнения'
    return false
  }

  if (digits.length < 10) {
    phoneError.value = 'Введите корректный номер телефона'
    return false
  }
  phoneError.value = ''
  return true
}

const contactByPhone = ref(false)
const contactByEmail = ref(false)
const contactByWhatsApp = ref(false)
const contactError = ref('')

const isPhoneRequired = computed(() => contactByPhone.value || contactByWhatsApp.value)
const isEmailRequired = computed(() => contactByEmail.value)
const bothRequired = computed(() => contactByEmail.value && (contactByPhone.value || contactByWhatsApp.value))

const validateForm = () => {
  let valid = true
  valid = validatePhone() & validateEmail() && valid
  valid = validateName() && valid
  return !!valid
}

const notification = ref("");
const notificationType = ref(""); // success или error

const submitForm = async () => {
  let data = {
    phone: phone.value,
    email: email.value,
    name: name.value,
  }
  if (validateForm()) {
    const orderData = {
      amount: Math.round(props.price * 100),
      returnUrl: window.location.origin + '/payment-callback',
      description: `Гайд: ${props.currentGuide.title}`,
      name: name.value,
      phone: phone.value,
      email: email.value,
    };
    if (props.currentGuide && props.currentGuide.id) {
      orderData.travel_guide = props.currentGuide.documentId;
    }
    try {
      const response = await axios.post('http://localhost:1337/api/tour-order/alfa-register', orderData, {
        headers: {
          Authorization: `Bearer ${config.public.API_ORDER_TOKEN}`,
        },
      });
      const result = response.data;
      if (result.formUrl) {
        window.location.href = result.formUrl;
      } else {
        notification.value = 'Ошибка при создании заказа: ' + (result.errorMessage || 'Неизвестная ошибка');
        notificationType.value = 'error';
      }
    } catch (e) {
      notification.value = 'Ошибка при соединении с сервером';
      notificationType.value = 'error';
    }
  }
}

const formatPrice = (price) => {
  const roundedPrice = Math.round(price);
  return roundedPrice.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
}

watch([contactByPhone, contactByEmail, contactByWhatsApp], () => {
  if (contactByPhone.value || contactByEmail.value || contactByWhatsApp.value) {
    contactError.value = '';
  }
});
</script>
<style scoped>
.popup-comp {
  padding: 150px 110px 105px;
  box-shadow: 0 0 60px 0 rgba(0, 0, 0, 0.38);
  backdrop-filter: blur(29px);
  border-radius: 16px;
  width: 65%;
  @media (max-width: 1200px) {
    width: 80%;
    padding: 100px 80px;
  }
  @media (max-width: 900px) {
    padding: 80px 40px;
  }
}

.prices {
  display: flex;
  align-items: flex-end;
}

.fix-price {
  font-weight: 700;
  font-size: 64px;
  line-height: 100%;
  vertical-align: middle;
  color: #FFFFFF;
  @media (max-width: 1600px) {
    font-size: 44px;
  }
  @media (max-width: 1400px) {
    font-size: 36px;
  }
  @media (max-width: 900px) {
    font-size: 20px;
  }
  @media (max-width: 576px) {
    font-size: 24px;
  }
}

.close-btn {
  position: absolute;
  top: 24px;
  right: 24px;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #fff;
  color: #D36A6A;
  font-size: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  border: 1px solid #D36A6A;
  transition: background 0.2s;
}

.button-pay {
  width: 395px;
  height: 134px;
  opacity: 1;
  border-radius: 24px;
  padding: 48px 126px;
  gap: 10px;
  background: #C75454;
  font-weight: 700;
  font-style: Bold;
  font-size: 36px;
  line-height: 100%;
  color: #FFFFFF;
  cursor:pointer;
  @media (max-width: 1400px) {
    width: 300px;
    height: 113px;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  @media (max-width: 1005px) {
    width: 200px;
    height: 83px;
    font-size: 30px;
  }
  @media (max-width: 600px) {
    width: 80px;
    height: 50px;
    font-size: 30px;
  }
  @media (max-width: 576px) {
    width: 45%;
    height: 40px;
    font-size: 14px;
    padding: 0;
    border-radius: 10px;
  }
}

.popup-pay {
  display: flex;
  justify-content: space-between;
  margin-top: 42px;
}

.popup-width {
  width: 100%;
}

.pop-in {
  position: relative;
}

.popup-label {
  position: absolute;
  z-index: 99999;
  top: 29px;
  left: 43px;
  font-family: Montserrat;
  font-weight: 500;
  font-size: 36px;
  line-height: 100%;
  color: #C3C3C3;
  transition: top 0.3s ease, font-size 0.3s ease, color 0.3s ease;
  pointer-events: none;
  @media (max-width: 1200px) {
    font-size: 18px;
    top: 14px;
    left: 13px;
  }
  @media (max-width: 576px) {
    font-size: 8px;
    top: 12px;
  }
}

.popup-input:focus-visible ~ .popup-label,
.popup-input:not(:placeholder-shown) ~ .popup-label {
  top: 10px;
  font-size: 24px;
}

.popup-header {
  font-weight: 700;
  font-size: 84px;
  line-height: 100%;
  @media (max-width: 1500px) {
    font-size: 65px;
  }
}

.popup-inputs {
  display: flex;
  flex-direction: column;
  gap: 15px;
}

.popup-input {
  width: 100%;
  height: 101px;
  padding: 16px 43px;
  border-radius: 17px;
  background: #FFFFFF;
  border: none;
  transition: border-color 0.3s ease;
  font-family: Montserrat;
  font-weight: 400;
  font-size: 26px;
  line-height: 100%;
  vertical-align: middle;
  border: 3px solid #D9D9D9;
  @media (max-width: 1200px) {
    height: 52px;
    border-radius: 10px;
    padding: 16px 15px;
    font-size: 15px;
  }
  @media (max-width: 768px) {
    height: 42px;
    border-radius: 8px;
    padding: 25px 14px;
    font-size: 13px;
  }
  @media (max-width: 576px) {
    height: 32px;
    border-radius: 6px;
    padding: 16px 13px;
    font-size: 8px;
  }
}

.popup-input.error {
  border: 2px solid #ff4444;
}

.error-message {
  color: #ff4444;
  font-family: Montserrat;
  font-size: 14px;
  margin-top: 5px;
  font-weight: 500;
}


.popup-checkbox label {
  display: inline-block;
  width: 45px;
  height: 45px;
  border: 3px solid #D9D9D9;
  background: #FFFFFF;
  border-radius: 10px;
  cursor: pointer;
  position: relative;
}

.popup-checkbox input[type="checkbox"]:checked + label::after {
  content: "";
  position: absolute;
  left: 9px;
  width: 15px;
  height: 25px;
  border: solid #C75454;
  border-width: 0 6px 6px 0;
  transform: rotate(45deg);
}

.popup-notification {
  margin-top: 20px;
  padding: 20px 30px;
  border-radius: 12px;
  font-size: 20px;
  font-weight: 600;
  text-align: center;
  width: 100%;
  box-sizing: border-box;
  @media (max-width: 1200px) {
    font-size: 18px;
    padding: 15px 25px;
  }
  @media (max-width: 768px) {
    font-size: 18px;
    padding: 10px 20px;
  }
  @media (max-width: 576px) {
    font-size: 12px;
    padding: 5px 15px;
  }
}

.popup-notification.success {
  background: #e6ffe6;
  color: #1a7f1a;
  border: 1px solid #1a7f1a;
}

.popup-notification.error {
  background: #ffe6e6;
  color: #c75454;
  border: 1px solid #c75454;
}

.popup-body > *:not(.popup-darken) {
  position: relative;
  z-index: 2;
}
</style>